function createAddendum(id){const c=state.contracts.find(x=>x.id===id);if(!c)return;openModal('Contract Addendum — '+c.ref,`<div class="grid2"><div class="field"><label>Addendum Reference</label><input id="adRef" value="${esc(c.ref)}-ADD-${String((c.addenda||[]).length+1).padStart(2,'0')}"></div><div class="field"><label>Effective Date</label><input id="adDate" type="date" value="${TODAY()}"></div><div class="field full"><label>Changes / Agreed Terms</label><textarea id="adText"></textarea></div><div class="field full"><label>Reason</label><textarea id="adReason"></textarea></div></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveAddendum">SAVE & PRINT ADDENDUM</button>`);document.getElementById('saveAddendum').onclick=()=>{const text=adText.value.trim(),reason=adReason.value.trim();if(!adRef.value.trim()||!text||!reason)return alert('Reference, changes and reason are mandatory.');const a={id:uid('ADD'),reference:adRef.value.trim(),date:adDate.value,text,reason,createdAt:new Date().toISOString(),createdBy:currentUser()};c.addenda=Array.isArray(c.addenda)?c.addenda:[];c.addenda.push(a);audit('Sales Contract','Addendum created',`${c.ref} · ${a.reference} · ${reason}`);closeModal();printShipmentDoc('CONTRACT ADDENDUM',pageDoc(c,'CONTRACT ADDENDUM',`<div class="docRefGrid"><div class="docRefBox"><b>Contract</b>${esc(c.ref)}</div><div class="docRefBox"><b>Addendum</b>${esc(a.reference)} · ${fmt(a.date)}</div></div><h3 class="docSection">AGREED CHANGES</h3><p>${esc(a.text).replace(/\n/g,'<br>')}</p><h3 class="docSection">REASON / RECORD</h3><p>${esc(a.reason)}</p>${signature(c)}`),c.seller);renderContracts()}}
function cancelContract(id){const c=state.contracts.find(x=>x.id===id);if(!c)return;const reason=requiredReason('Mandatory reason for cancelling '+c.ref+':');if(!reason)return;snapshot(c,reason,'Cancelled');c.status='Cancelled';c.cancelled=true;c.cancelReason=reason;c.cancelledAt=new Date().toISOString();c.cancelledBy=currentUser();for(const s of state.shipments.filter(x=>x.contractRef===c.ref&&!x.completed)){s.cancelled=true;s.cancelReason=reason;s.status='Cancelled'}audit('Sales Contract','Cancelled',`${c.ref} · ${reason}`);renderContracts()}
