function confirmShipmentDelete__legacy_v0(processId){const p=state.shipments.find(x=>x.id===processId&&x.kind!=='lot');if(!p)return renderHome();view='home';renderNav();document.getElementById('main').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Are you sure you want to delete this shipment?</h2><div class="metaText">${esc(p.contractRef)} · ${esc(p.buyer||'')}</div></div></div><div class="notice warn" style="margin-top:14px"><b>This cannot be undone.</b> The shipment process, all its lots and uploaded documents, and linked Milling instructions/loading data will be deleted. The Sales Contract, customer/master records, Accounts data and audit history will remain.</div><div id="shipmentDeleteError" class="notice bad" style="display:none;margin-top:12px"></div><div class="toolbar" style="margin-top:16px"><div class="spacer"></div><button class="btn" id="keepShipment">No — Keep Shipment</button><button class="btn red" id="deleteShipmentYes">Yes — Delete Shipment</button></div></div>`;document.getElementById('keepShipment').onclick=renderHome;document.getElementById('deleteShipmentYes').onclick=async()=>{const button=document.getElementById('deleteShipmentYes'),error=document.getElementById('shipmentDeleteError');button.disabled=true;button.textContent='Deleting…';try{await deleteShipmentDocuments(p.contractRef)}catch(e){error.textContent=e.message||'Shipment documents could not be deleted. Nothing was changed.';error.style.display='block';button.disabled=false;button.textContent='Yes — Delete Shipment';return}const result=deleteShipmentData(processId);audit('Shipment','Permanently deleted after confirmation',result.contractRef+' · '+result.shipmentCount+' shipment record(s) · '+result.lotCount+' lot(s)');window.TT_SHARED_SYNC?.bridge?.();renderHome()}}
