 if(s.seller==='TG')add(SELLERS.TG,'Trans Grains (seller)');add(s.buyer||buyer?.name,'Buyer — '+(s.buyer||buyer?.name||''));
 for(const notify of buyer?.notifies||[])add(notify.name||notify,`Buyer related party — ${notify.name||notify}`);
 for(const name of [s.lc?.issuingBank,s.lc?.advisingBank])add(name,`L/C bank — ${name||''}`);
