 if(docHsCode(s,dc))lines.push(`HS CODE: ${docHsCode(s,dc)}`);lines.push(`TOTAL NET WEIGHT: ${(num(t.net)/1000).toFixed(3)} MT / ${num(t.net).toFixed(3)} KG`,`TOTAL GROSS WEIGHT: ${(num(t.gross)/1000).toFixed(3)} MT / ${num(t.gross).toFixed(3)} KG`);
 if(refs.gd)lines.push(`GD NO. / DATE: ${refs.gd}`);if(refs.fi)lines.push(`FI NO. / DATE: ${refs.fi}`);if(lcApplies(s,c)){if(s.lc?.lcNo)lines.push(`L/C NO.: ${s.lc.lcNo}`);if(s.lc?.lcDate)lines.push(`L/C ISSUING DATE: ${fmt(s.lc.lcDate)}`);if(s.lc?.issuingBank)lines.push(`L/C ISSUING BANK: ${s.lc.issuingBank}`)}return lines.filter(Boolean).join('\n')
